import java.util.*;
import java.io.*;

public class Main {
    static String[] classify(String[] passwords, String[] words) {
        // Write your solution here
        String[] res = new String[passwords.length];
        Arrays.fill(res, "strong");
        return res;
    }

    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        String[] passwords = new String[n], words = new String[m];
        for (int i = 0; i < n; i++) passwords[i] = st.nextToken();
        for (int i = 0; i < m; i++) words[i] = st.nextToken();
        StringBuilder sb = new StringBuilder();
        for (String r : classify(passwords, words)) sb.append(r).append("\n");
        System.out.print(sb);
    }
}
